  const parseColor=(value)=>{const v=String(value||'').trim().toLowerCase();if(!v||v==='transparent'||v==='rgba(0, 0, 0, 0)')return null;const hex=v.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/);if(hex){const h=hex[1].length===3?hex[1].split('').map(c=>c+c).join(''):hex[1];return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16));}const rgb=v.match(/^rgba?\(([^)]+)\)$/);if(rgb){const p=rgb[1].split(/[\/\s,]+/).filter(Boolean).map(Number);if(p.length>=3&&p.slice(0,3).every(n=>Number.isFinite(n)&&n>=0&&n<=255))return p.slice(0,3);}return null;};
